#pragma once
#include "crypto.hpp"
namespace vpn {
inline bool tls_profile_supported(const std::string& name){return std::set<std::string>{"","unsafe","native","chrome","firefox","safari","ios","android","edge","360","qq","random","randomized"}.count(lower(trim(name)))!=0;}
inline std::vector<std::string> tls_option_list(const Config& c,std::initializer_list<const char*> keys){auto value=option(c.original_options,keys);if(value.empty())return {};if(value[0]=='['){auto j=json_parse(value);if(j.kind!=Json::Array)throw std::runtime_error("PARSE_INVALID: TLS list");std::vector<std::string> out;for(const auto& v:j.array){if(v.kind!=Json::String)throw std::runtime_error("PARSE_INVALID: TLS list element");out.push_back(v.text);}return out;}std::vector<std::string> out;std::istringstream in(value);std::string item;while(std::getline(in,item,',')){item=trim(item);if(!item.empty())out.push_back(item);}return out;}
inline std::vector<std::string> certificate_pins(const Config& c){auto pins=tls_option_list(c,{"pcs","pinnedpeercertsha256","pinned-peer-cert-sha256","pinsha256"});for(auto& p:pins){if(p.size()==64&&p.find_first_not_of("0123456789abcdefABCDEF")==std::string::npos){p=lower(p);continue;}if(p.find("sha256/")==0)p=p.substr(7);else if(p.find("sha256-")==0)p=p.substr(7);auto bytes=b64_decode(p);if(bytes.size()!=32)throw std::runtime_error("PARSE_INVALID: certificate pin must be SHA256");p=hex_bytes(bytes);}if(pins.size()>32)throw std::runtime_error("PARSE_INVALID: certificate pin count");return pins;}
inline std::vector<std::string> certificate_names(const Config& c){auto names=tls_option_list(c,{"vcn","verifypeercertbyname","verify-peer-cert-by-name"});for(auto& name:names)check_host(name);if(names.size()>32)throw std::runtime_error("PARSE_INVALID: certificate name count");return names;}
}
